410	 * POST a tiny test multipart to `${publicUrl}/photo-upload` and report what
411	 * comes back. Used inside the photo-timeout error path to disambiguate
412	 * "tunnel is dead" from "cloud sent the wrong URL".
413	 *
414	 * Expected outcome on a healthy tunnel: HTTP 404 with body
415	 * `{"success":false,"error":"No pending request found for this photo (...)"}`
416	 * — that's the SDK's `/photo-upload` route correctly bouncing a request
417	 * with no matching pending photo. Anything else (network error, 5xx,
418	 * 502 from the tunnel) means the path the glasses use can't reach us.
419	 */
420	async function probePhotoUpload(publicUrl: string): Promise<string> {
421	  const target = `${publicUrl}/photo-upload`;
422	  const ctrl = new AbortController();
423	  const t = setTimeout(() => ctrl.abort(), 7000);
424	  try {
425	    const form = new FormData();
426	    form.append("requestId", "self-probe");
427	    const res = await fetch(target, { method: "POST", body: form, signal: ctrl.signal });
428	    clearTimeout(t);
429	    const text = await res.text().catch(() => "");
430	    const trimmed = text.length > 200 ? `${text.slice(0, 200)}…` : text;
431	    if (res.status === 404) {
432	      return `✅ tunnel reachable (HTTP 404 — expected; SDK says "no pending request for this photo")`;
