  /** Push a photo to all connected SSE clients */
  broadcastPhoto(photo: StoredPhoto): void {
    const base64Data = photo.buffer.toString("base64");
    const payload = JSON.stringify({
      requestId: photo.requestId,
      timestamp: photo.timestamp.getTime(),
      mimeType: photo.mimeType,
      filename: photo.filename,
      size: photo.size,
      userId: photo.userId,
      base64: base64Data,
      dataUrl: `data:${photo.mimeType};base64,${base64Data}`,
      // COMMENTED OUT: YOLO detection fields - focusing on basic photo capture first
      // detections: photo.detections ?? null,
      // width: photo.width ?? null,
      // height: photo.height ?? null,
    });

    for (const client of this.sseClients) {
      try {
        client.write(payload);
      } catch {
        this.sseClients.delete(client);
      }
    }
  }

  getPhoto(requestId: string): StoredPhoto | undefined {
    return this.photos.get(requestId);
  }

  /** All photos for this user, sorted newest-first */
  getAll(): StoredPhoto[] {
    return Array.from(this.photos.values()).sort(
      (a, b) => b.timestamp.getTime() - a.timestamp.getTime(),
    );
  }

  /** The full photos map (used by SSE to send history on connect) */
  getAllMap(): Map<string, StoredPhoto> {
    return this.photos;
  }

  removeAll(): void {
    this.photos.clear();
  }

  /** Drop the oldest stored photos once we exceed MAX_STORED_PHOTOS. */
  private evictOldPhotos(): void {
    const overflow = this.photos.size - PhotoManager.MAX_STORED_PHOTOS;
    if (overflow <= 0) return;
    // Map iteration order is insertion order, so the first N keys are oldest.
    const it = this.photos.keys();
    for (let i = 0; i < overflow; i++) {
      const key = it.next().value;
      if (key) this.photos.delete(key);
    }
  }

  addSSEClient(client: SSEWriter): void {
    this.sseClients.add(client);
  }

  removeSSEClient(client: SSEWriter): void {
    this.sseClients.delete(client);
  }

  /** Tear down — clear photos and SSE clients */
  destroy(): void {
    // COMMENTED OUT: Live Scan and food tracking - focusing on basic photo capture first
    // this.stopLiveScan();
    // this.foodsInView.clear();
    this.photos.clear();
    this.sseClients.clear();
  }
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * POST a tiny test multipart to `${publicUrl}/photo-upload` and report what
 * comes back. Used inside the photo-timeout error path to disambiguate
 * "tunnel is dead" from "cloud sent the wrong URL".
 *
 * Expected outcome on a healthy tunnel: HTTP 404 with body
 * `{"success":false,"error":"No pending request found for this photo (...)"}`
 * — that's the SDK's `/photo-upload` route correctly bouncing a request
 * with no matching pending photo. Anything else (network error, 5xx,
 * 502 from the tunnel) means the path the glasses use can't reach us.
 */
async function probePhotoUpload(publicUrl: string): Promise<string> {
  const target = `${publicUrl}/photo-upload`;
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), 7000);
  try {
    const form = new FormData();
    form.append("requestId", "self-probe");
    const res = await fetch(target, { method: "POST", body: form, signal: ctrl.signal });
    clearTimeout(t);
    const text = await res.text().catch(() => "");
    const trimmed = text.length > 200 ? `${text.slice(0, 200)}…` : text;
    if (res.status === 404) {
      return `✅ tunnel reachable (HTTP 404 — expected; SDK says "no pending request for this photo")`;
    }
    if (res.status >= 200 && res.status < 300) {
      return `⚠️  HTTP ${res.status} — the route accepted a stub upload, which is unexpected. Body: ${trimmed}`;
    }
    return `❌ HTTP ${res.status} ${res.statusText} — tunnel/server reachable but /photo-upload rejected. Body: ${trimmed}`;
  } catch (err) {
    clearTimeout(t);
    return `❌ unreachable: ${err instanceof Error ? err.message : String(err)} — tunnel down, wrong PUBLIC_URL, or DNS issue`;
  }
}

